// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "0", "0"); }
    function testFuzz_property(uint256 amount) public {
        uint256 initialSupply = 1000 * 10**uint256(c.decimals());
        vm.assume(amount > 0 && amount <= initialSupply);

        vm.prank(address(this));
        c.mintToken(address(this), initialSupply);
        vm.prank(address(this));
        c.burn(amount);

        assertEq(c.totalSupply(), c.balanceOf(address(this)));
    }
}
